{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 9,
      "text_ar": "رأيت وأشفقت عليهم، ولكن ليس كثيراً، وخلصت لنفسي عنبة من عنقود، ونبْتَةً من غابة عظيمة.",
      "verse": 21
    },
    {
      "chapter": 9,
      "text_ar": "فلتهلك إذن الجمهور الذين ولدوا عبثاً، ولتخلص عنبتي ونبتتي، لأني قد أكملتهما بعناء عظيم.",
      "verse": 22
    },
    {
      "chapter": 9,
      "text_ar": "ولكن، إذا انتظرت سبعة أيام أخرى - ومع ذلك فلا تصم فيها -",
      "verse": 23
    },
    {
      "chapter": 9,
      "text_ar": "بل اذهب إلى حقل من الزهور، حيث لم يُبنَ بيت، وكل من زهور الحقل وحدها، ولا تذق لحماً، ولا تشرب خمراً، بل كل زهوراً فقط -",
      "verse": 24
    },
    {
      "chapter": 9,
      "text_ar": "وصلِّ إلى العلي باستمرار، فحينئذ آتي وأتكلم معك.",
      "verse": 25
    }
  ]
}
